using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class BuildEvent164 {
 const string D="Assets/Events/NewYear";static Material snow,red,gold,green;static Dictionary<UnityEngine.Object,UnityEngine.Object> enemies=new Dictionary<UnityEngine.Object,UnityEngine.Object>();
 static Material Mat(string n,Color c){var p=D+"/"+n+".mat";var m=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/Prefabs/Workshop/LobbyIsland/Winter128/Powder_Snow.mat"));m.name=n;m.color=c;AssetDatabase.CreateAsset(m,p);return m;}
 static GameObject Shape(Transform root,string n,PrimitiveType t,Vector3 p,Vector3 scale,Material m){var o=GameObject.CreatePrimitive(t);o.name=n;o.transform.SetParent(root,false);o.transform.localPosition=p;o.transform.localScale=scale;o.GetComponent<Renderer>().sharedMaterial=m;UnityEngine.Object.DestroyImmediate(o.GetComponent<Collider>());return o;}
 static Bounds BoundsOf(GameObject o){var rr=o.GetComponentsInChildren<Renderer>().Where(r=>r.gameObject.activeInHierarchy).ToArray();var b=rr.Length>0?rr[0].bounds:new Bounds(o.transform.position,Vector3.one);foreach(var r in rr)b.Encapsulate(r.bounds);return b;}
 static GameObject Group(GameObject o,string n){var g=new GameObject(n);g.transform.SetParent(o.transform,false);return g;}
 static void Gift(Transform p,Vector3 pos,float s){Shape(p,"Wrapped_Gift",PrimitiveType.Cube,pos,new Vector3(s,s,s),red);Shape(p,"Gold_Ribbon",PrimitiveType.Cube,pos+Vector3.up*(s*.51f),new Vector3(s*1.04f,.04f,s*.17f),gold);Shape(p,"Gold_Ribbon_Cross",PrimitiveType.Cube,pos+Vector3.up*(s*.52f),new Vector3(s*.17f,.04f,s*1.04f),gold);}
 static void Hat(GameObject o){var b=BoundsOf(o);var head=o.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name.ToLower().Contains("head")&&!t.name.ToLower().Contains("headtop"));var g=Group(o,"NewYear_Cosmetics");if(head){g.transform.SetParent(head,false);g.transform.position=new Vector3(b.center.x,b.max.y-.08f,b.center.z);}else g.transform.position=new Vector3(b.center.x,b.max.y-.08f,b.center.z);float s=Mathf.Clamp(b.size.y*.16f,.18f,2.5f);Shape(g.transform,"Snow_Trim",PrimitiveType.Sphere,Vector3.zero,new Vector3(s*1.9f,s*.4f,s*1.7f),snow);Shape(g.transform,"Ruby_Hat",PrimitiveType.Sphere,Vector3.up*s*.55f,new Vector3(s*1.5f,s*1.6f,s*1.4f),red);Shape(g.transform,"Snow_Pom",PrimitiveType.Sphere,new Vector3(s*.35f,s*1.4f,0),Vector3.one*s*.55f,snow);}
 static GameObject CopyPrefab(string src,string name,Action<GameObject> edit){var dest=D+"/"+name+".prefab";if(!AssetDatabase.CopyAsset(src,dest))throw new Exception("Copy failed "+dest);var o=PrefabUtility.LoadPrefabContents(dest);try{o.name=name;edit(o);PrefabUtility.SaveAsPrefabAsset(o,dest);}finally{PrefabUtility.UnloadPrefabContents(o);}return AssetDatabase.LoadAssetAtPath<GameObject>(dest);}
 static void Remap(GameObject o){foreach(var c in o.GetComponentsInChildren<MonoBehaviour>(true)){if(!c)continue;var so=new SerializedObject(c);var it=so.GetIterator();bool dirty=false;while(it.Next(true)){if(it.propertyType==SerializedPropertyType.ObjectReference&&it.objectReferenceValue!=null&&enemies.TryGetValue(it.objectReferenceValue,out var v)){it.objectReferenceValue=v;dirty=true;}}if(dirty)so.ApplyModifiedPropertiesWithoutUndo();}}
 static void DressPlace(GameObject o){var b=BoundsOf(o);var g=Group(o,"NewYear_Decoration");float floor=b.min.y; // use side decorations, keep all gameplay paths clear
 foreach(int side in new[]{-1,1}){float x=b.center.x+side*b.size.x*.42f;for(int i=0;i<5;i++){float z=Mathf.Lerp(b.min.z,b.max.z,(i+1)/6f);var p=new Vector3(x,Mathf.Max(0,floor)+.2f,z);Shape(g.transform,"Side_Snowdrift",PrimitiveType.Sphere,p,new Vector3(3.8f,.55f,2.3f),snow);if(i%2==0)Gift(g.transform,p+new Vector3(.5f,.5f,.4f),.8f);}}
 for(int i=0;i<15;i++){var p=new Vector3(Mathf.Lerp(b.min.x,b.max.x,(i+1)/16f),b.max.y*.8f,b.center.z);Shape(g.transform,"Festive_Ornament",PrimitiveType.Sphere,p,Vector3.one*.55f,i%2==0?gold:red);}
 Remap(o);}
 static void SetRef(Component c,string prop,UnityEngine.Object value){var so=new SerializedObject(c);var p=so.FindProperty(prop);if(p==null)throw new Exception(c.GetType()+" missing "+prop);p.objectReferenceValue=value;so.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Stop play first");if(AssetDatabase.IsValidFolder(D))throw new Exception("Event assets exist; no overwrite");Directory.CreateDirectory(D);AssetDatabase.Refresh();snow=Mat("Snow",new Color(.88f,.95f,1));red=Mat("Ruby",new Color(.65f,.025f,.06f));gold=Mat("Gold",new Color(1,.64f,.13f));green=Mat("Fir",new Color(.025f,.17f,.10f));
 var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Locations/Spawner/Spawners.prefab");var zs=source.GetComponentInChildren<ZombieSpawner>(true);var zso=new SerializedObject(zs);var types=zso.FindProperty("enemyTypes");for(int i=0;i<types.arraySize;i++){var original=types.GetArrayElementAtIndex(i).objectReferenceValue as ZombieController;if(original==null||enemies.ContainsKey(original))continue;var clone=CopyPrefab(AssetDatabase.GetAssetPath(original),"NY_"+original.name,Hat);enemies[original]=clone.GetComponent<ZombieController>();}
 var boss=CopyPrefab("Assets/Prefabs/Enemy/BossTentacles.prefab","NY_BossTentacles",o=>{Hat(o);Remap(o);});
 var castle=CopyPrefab("Assets/Prefabs/Locations/Castle.prefab","NY_Castle",DressPlace);
 var ruins=CopyPrefab("Assets/Prefabs/Locations/Enemy/ruins_1.prefab","NY_Ruins_1",DressPlace);
 var fir=CopyPrefab("Assets/Prefabs/Locations/Decoration/Hilly_Prop_Tree_Pine_1.prefab","NY_FestiveFir",o=>{var b=BoundsOf(o);var g=Group(o,"NewYear_Decoration");for(int i=0;i<18;i++){float y=b.min.y+b.size.y*(.2f+.65f*(i%6)/6f);float a=i*2.39996f;float r=b.size.x*.33f*(1-(y-b.min.y)/b.size.y);Shape(g.transform,"Bauble",PrimitiveType.Sphere,new Vector3(b.center.x+Mathf.Cos(a)*r,y,b.center.z+Mathf.Sin(a)*r),Vector3.one*Mathf.Max(.16f,b.size.y*.025f),i%2==0?gold:red);}Shape(g.transform,"Tree_Topper",PrimitiveType.Sphere,new Vector3(b.center.x,b.max.y,b.center.z),Vector3.one*.5f,gold);Gift(g.transform,new Vector3(b.center.x+.6f,b.min.y+.35f,b.center.z),.7f);});
 AssetDatabase.CopyAsset("Assets/Scripts/Locations/DecorationSpawnCollectionForest.asset",D+"/NY_Decor.asset");var decor=AssetDatabase.LoadAssetAtPath<DecorationSpawnCollection>(D+"/NY_Decor.asset");decor.spawnItems.Add(new DecorationSpawnItem{prefab=fir,chance=100});EditorUtility.SetDirty(decor);
 AssetDatabase.CopyAsset("Assets/Scripts/Locations/LocationSpawnCollectionForest.asset",D+"/NY_Locations.asset");var loc=AssetDatabase.LoadAssetAtPath<LocationSpawnCollection>(D+"/NY_Locations.asset");var ls=new SerializedObject(loc);var entries=ls.FindProperty("spawnItems");int replaced=0;for(int i=0;i<entries.arraySize;i++){var pp=entries.GetArrayElementAtIndex(i).FindPropertyRelative("prefab");if(pp.objectReferenceValue!=null&&AssetDatabase.GetAssetPath(pp.objectReferenceValue)=="Assets/Prefabs/Locations/Enemy/ruins_1.prefab"){pp.objectReferenceValue=ruins.GetComponent<LocationContentSpawner>();replaced++;}}if(replaced!=1)throw new Exception("Expected one ruins entry, got "+replaced);ls.ApplyModifiedPropertiesWithoutUndo();
 AssetDatabase.CopyAsset("Assets/Scripts/Locations/Items/LocationItemSpawnCollectionForest.asset",D+"/NY_Loot.asset");AssetDatabase.CopyAsset("Assets/Resources/LocationBalanceProfile.asset",D+"/NY_Balance.asset");var balance=AssetDatabase.LoadAssetAtPath<LocationBalanceProfile>(D+"/NY_Balance.asset");var bs=new SerializedObject(balance);var arr=bs.FindProperty("_sceneBalances");arr.InsertArrayElementAtIndex(0);var b0=arr.GetArrayElementAtIndex(0);b0.FindPropertyRelative("sceneName").stringValue="LevelEvent";b0.FindPropertyRelative("itemCollectionOverride").objectReferenceValue=AssetDatabase.LoadAssetAtPath<LocationItemSpawnCollection>(D+"/NY_Loot.asset");bs.ApplyModifiedPropertiesWithoutUndo();
 // All generated locations use this per-scene entry via Resources fallback. Add only Event, preserve all existing biome settings.
 var global=AssetDatabase.LoadAssetAtPath<LocationBalanceProfile>("Assets/Resources/LocationBalanceProfile.asset");var gs=new SerializedObject(global);var ga=gs.FindProperty("_sceneBalances");if(global.SceneBalances.Any(x=>x.sceneName=="LevelEvent"))throw new Exception("Event balance already exists");ga.InsertArrayElementAtIndex(0);var e=ga.GetArrayElementAtIndex(0);e.FindPropertyRelative("sceneName").stringValue="LevelEvent";e.FindPropertyRelative("itemCollectionOverride").objectReferenceValue=AssetDatabase.LoadAssetAtPath<LocationItemSpawnCollection>(D+"/NY_Loot.asset");gs.ApplyModifiedPropertiesWithoutUndo();
 AssetDatabase.SaveAssets();var path="Assets/Scenes/LevelEvent.unity";var text=File.ReadAllText(path);text=text.Replace(AssetDatabase.AssetPathToGUID("Assets/Prefabs/Locations/Castle.prefab"),AssetDatabase.AssetPathToGUID(D+"/NY_Castle.prefab"));File.WriteAllText(path,text);AssetDatabase.ImportAsset(path);var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Additive);foreach(var root in scene.GetRootGameObjects()){foreach(var c in root.GetComponentsInChildren<LocationSpawner>(true))SetRef(c,"locationCollection",loc);foreach(var c in root.GetComponentsInChildren<DecorationSpawner>(true))SetRef(c,"decorationCollection",decor);foreach(var c in root.GetComponentsInChildren<CitySpawner>(true))SetRef(c,"cityPrefab",castle);foreach(var c in root.GetComponentsInChildren<BossSpawner>(true))SetRef(c,"_boss",boss.GetComponent<TriggerBossFight>());Remap(root);}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();return "Created NewYear assets; event scene wired; forest balance copied; sample ruins, five enemy looks, fir, castle and boss. Other open scenes untouched.";}
}